        /* ===== ☆ 咏唱特效：金色脉动光晕（咏唱中/咏唱完成待释放） ===== */
                /* ===== 判定区块（体系色由 --phase/--wash 注入） ===== */
        .phase-block { position: relative; margin: 10px 0 16px; padding: 8px 14px 12px 12px; background: linear-gradient(135deg, var(--wash, rgba(232,214,178,.32)), rgba(232,214,178,.30)); border: 1px solid rgba(160,120,64,.28); border-left: 2px solid var(--phase, #c4a050); border-radius: 4px; box-shadow: inset 0 1px 8px rgba(120,80,30,.09), inset 0 -2px 10px rgba(120,80,30,.06); }
