        /* ============================================================
           渲染设置面板：右上角齿轮，勾选即开关对应正则/功能
        ============================================================ */
        .settings-fab { position: fixed; right: 12px; top: 12px; width: 34px; height: 34px; border-radius: 50%; z-index: 999; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 17px; line-height: 1; border: 1px solid rgba(160,120,64,.45); background: linear-gradient(180deg, #f2e3c0, #e4cf9f); color: #6a4a1a; box-shadow: 0 2px 6px rgba(0,0,0,.28); transition: transform .15s, background .15s; user-select: none; }
        .settings-fab:hover { transform: rotate(30deg); }
        .settings-fab.active { background: linear-gradient(180deg, #d4af37, #b8892a); color: #fff; }
        .settings-panel { position: fixed; right: 12px; top: 52px; width: 240px; z-index: 999; border-radius: 6px; background: #f7ecd4; border: 1px solid #a07840; box-shadow: 0 8px 24px rgba(0,0,0,.35); padding: 10px 13px 8px; font-size: .82em; display: none; }
        .settings-panel.open { display: block; }
        .settings-head { font-weight: 700; color: #5a3a08; letter-spacing: 1px; border-bottom: 1px dashed #c4a050; padding-bottom: 5px; margin-bottom: 6px; display: flex; justify-content: space-between; align-items: center; }
        .settings-close { cursor: pointer; color: #8a6a3a; font-size: 13px; }
        .settings-group { margin: 4px 0; }
