        .setting-item { display: flex; align-items: center; gap: 6px; color: #4a3218; padding: 1.5px 0; cursor: pointer; }
        .setting-item input { cursor: pointer; accent-color: #a07828; margin: 0; }
        .settings-foot { border-top: 1px dashed #c4a050; margin-top: 6px; padding-top: 6px; display: flex; justify-content: space-between; align-items: center; }
        .settings-foot button { cursor: pointer; background: linear-gradient(180deg,#a07840,#8a5a2a); color:#fff; border: none; border-radius: 3px; padding: 3px 10px; font-size: .8em; font-family: inherit; }
        .settings-saved { color: #3a7a4a; font-size: .76em; opacity: 0; transition: opacity .3s; }
        .settings-saved.show { opacity: 1; }
        body.apocalypse .settings-fab { background: linear-gradient(180deg,#3a2a3a,#2a1e2a); color:#b89ab8; border-color:#6a4a6a; }
        body.apocalypse .settings-fab.active { background: linear-gradient(180deg,#8a4a6a,#5a3050); color:#fff; }
        body.apocalypse .settings-panel { background:#2a1f2a; border-color:#6a4a6a; color:#d8c8d8; box-shadow: 0 8px 24px rgba(0,0,0,.6); }
