        body.apocalypse .setting-item { color:#c8b0c8; }
        body.apocalypse .settings-close { color:#9a7a9a; }
        body.apocalypse .settings-foot { border-color:#6a4a6a; }
        body.apocalypse .settings-foot button { background: linear-gradient(180deg,#6a4a6a,#4a304a); }
        /* 关闭流派特效：隐藏角标与背景纹理（保留整块流派色） */
        body.flowfx-off .phase-block[class*="elem-"]::after { display: none; }
        body.flowfx-off .phase-block[class*="elem-"] { background: var(--wash, linear-gradient(135deg, rgba(232,214,178,.32), rgba(232,214,178,.30))); box-shadow: inset 0 1px 6px rgba(120,80,30,.06); }
        body.apocalypse.flowfx-off .phase-block[class*="elem-"] { background: var(--wash, linear-gradient(135deg, rgba(42,16,34,.4), rgba(20,10,16,.32))); box-shadow: inset 0 0 22px rgba(0,0,0,.42); }

        /* ===== 位阶徽章：从变量读角色等阶，显示在资源条旁 ===== */
        .rank-badge { display: inline-block; padding: 1px 10px; border-radius: 10px; font-size: .8em; font-weight: 800; letter-spacing: 1px; border: 1px solid; margin: 0 2px 0 4px; vertical-align: middle; line-height: 1.5; }
        .rank-普通 { background: linear-gradient(135deg, #efe9dc, #e2d9c6); border-color: #9a9068; color: #5a5240; }
        .rank-超凡 { background: linear-gradient(135deg, #dceadf, #c9ddcd); border-color: #2f8a6a; color: #14402e; }
        .rank-精英 { background: linear-gradient(135deg, #dbe4f2, #c8d6ea); border-color: #2a5a9a; color: #12305a; }
