        .rank-神话 { background: linear-gradient(135deg, #faf0c8, #f2dd9a); border-color: #c9a227; color: #5a4200; box-shadow: 0 0 8px rgba(201,162,39,.45); }
        body.apocalypse .rank-badge { color: #d8c8d8; }
        body.apocalypse .rank-普通 { background: rgba(40,28,40,.85); border-color: #6a4a5a; color: #c0a8b8; }
        body.apocalypse .rank-超凡 { background: linear-gradient(180deg, rgba(40,160,90,.35), rgba(20,90,50,.15)); border-color: #2ac07a; color: #8affc0; text-shadow: 0 0 6px rgba(58,224,138,.4); }
        body.apocalypse .rank-精英 { background: linear-gradient(180deg, rgba(40,80,180,.35), rgba(20,50,120,.15)); border-color: #4a6ae0; color: #9ab4ff; text-shadow: 0 0 6px rgba(80,120,255,.35); }
        body.apocalypse .rank-史诗 { background: linear-gradient(180deg, rgba(120,60,200,.35), rgba(70,30,130,.15)); border-color: #8a5ae0; color: #c8a8ff; text-shadow: 0 0 6px rgba(140,90,255,.35); }
        body.apocalypse .rank-传说 { background: linear-gradient(180deg, rgba(200,120,40,.35), rgba(130,70,20,.15)); border-color: #e0a040; color: #ffd0a0; text-shadow: 0 0 6px rgba(255,160,60,.35); }
        body.apocalypse .rank-神话 { background: linear-gradient(180deg, rgba(200,40,60,.4), rgba(120,20,40,.2)); border-color: #ff2a4a; color: #ffd0d8; text-shadow: 0 0 10px rgba(255,42,74,.7); box-shadow: 0 0 10px rgba(255,42,74,.5); }
    </style>
</head>
<body>
    <div id="rawData" style="display:none;">$1</div>
    <!-- 渲染设置：右上角齿轮，勾选即开关对应正则/功能；设置会存入浏览器并同步到酒馆聊天变量「战斗轮渲染设置」 -->
    <div class="settings-fab" id="settingsFab" title="羊皮卷渲染设置">⚙</div>
    <div class="settings-panel" id="settingsPanel">
        <div class="settings-head">羊皮卷渲染设置 <span class="settings-close" id="settingsClose">✕</span></div>
        <div class="settings-group">
            <div class="settings-title">— 渲染风格 —</div>
            <label class="setting-item"><input type="checkbox" data-key="flowStyle"> 七大流派整块染色</label>
            <label class="setting-item"><input type="checkbox" data-key="flowFx"> 流派角标与纹理特效</label>
            <label class="setting-item"><input type="checkbox" data-key="critHighlight"> 暴击/大失败/升级高亮</label>
        </div>
        <div class="settings-group">
            <div class="settings-title">— 解析兼容 —</div>
            <label class="setting-item"><input type="checkbox" data-key="fullWidth"> 全角符号兼容（：｜→）</label>
            <label class="setting-item"><input type="checkbox" data-key="charBox"> 角色状态紧凑灰框</label>
            <label class="setting-item"><input type="checkbox" data-key="groupStatus"> 群状态一行格式</label>
            <label class="setting-item"><input type="checkbox" data-key="resourceBar"> 资源条彩色填充</label>
            <label class="setting-item"><input type="checkbox" data-key="rankBadge"> 位阶徽章</label>
        </div>
        <div class="settings-group">
            <div class="settings-title">— 主题与界面 —</div>
            <label class="setting-item"><input type="checkbox" data-key="apocalypseForce"> 强制暗黑风</label>
            <label class="setting-item"><input type="checkbox" data-key="apocalypseBlock"> 禁用暗黑风</label>
            <label class="setting-item"><input type="checkbox" data-key="headSub"> 卷首题头</label>
        </div>
        <div class="settings-foot">
            <button id="settingsReset">恢复默认</button>
            <span class="settings-saved" id="settingsSaved">已保存 ✓</span>
        </div>
    </div>
    <div class="stage">
        <div class="scroll-frame">
            <div class="roller roller-top"><i class="cap c-l"></i><i class="cap c-r"></i></div>
            <div class="scroll">
                <span class="stain stain-1"></span>
                <span class="stain stain-2"></span>
                <div class="fog"></div>
                <div class="ash"></div>
                <div class="content" id="battleContent">
                    <div style="text-align:center; color:#8b6914; font-weight:600; letter-spacing:2px;">─ 展开羊皮卷中 ─</div>
                </div>
            </div>
            <div class="roller roller-bottom"><i class="cap c-l"></i><i class="cap c-r"></i></div>
        </div>
    </div>
    <script>
        // ===== 判定类型配色：按世界观三系 + 元素着色 =====
        var TYPE_COLORS = {
            '武技': { c: '#9a3b2a', i: '⚔' }, '战技': { c: '#a06020', i: '⚒' }, '魔法': { c: '#2a4a8a', i: '✧' }, '神术': { c: '#b8892a', i: '☀' },
            '火': { c: '#c0392b', i: '🔥' }, '水': { c: '#1f5fa8', i: '💧' }, '风': { c: '#2e8b74', i: '🌪️' },
            '雷': { c: '#c9a227', i: '⚡' }, '冰': { c: '#6a9ac0', i: '❄️' }, '土': { c: '#9a7a3a', i: '⛰️' },
            '符文': { c: '#3a5a4a', i: '✳️' }, '塑能': { c: '#4a3a6a', i: '✹' }, '死灵': { c: '#5a3a4a', i: '💀' }, '召唤': { c: '#4a3a6a', i: '✶' }, '暗能': { c: '#3a2a3a', i: '🌑' },
            '锻造': { c: '#8a4a1a', i: '🔨' }, '炼金': { c: '#2f6a4a', i: '⚗️' }, '工艺': { c: '#7a5a2a', i: '🛠' }
        };
        function hexA(hex, a) {
            var n = parseInt(hex.slice(1), 16);
            return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')';
        }
        function getTypeMeta(text) {
            var t = text || '';
            if (/符文/.test(t)) return TYPE_COLORS['符文'];
            if (/塑能/.test(t)) return TYPE_COLORS['塑能'];
            if (/死灵|尸术|灵术|亡灵/.test(t)) return TYPE_COLORS['死灵'];
            if (/召唤/.test(t)) return TYPE_COLORS['召唤'];
            if (/暗能|暗影|虚空/.test(t)) return TYPE_COLORS['暗能'];
            if (/神术|圣光|信仰/.test(t)) return TYPE_COLORS['神术'];
            if (/魔法|术式|术士/.test(t)) {
                if (/火/.test(t)) return TYPE_COLORS['火'];
                if (/水/.test(t)) return TYPE_COLORS['水'];
                if (/风/.test(t)) return TYPE_COLORS['风'];
                if (/雷/.test(t)) return TYPE_COLORS['雷'];
                if (/冰/.test(t)) return TYPE_COLORS['冰'];
                if (/土|岩/.test(t)) return TYPE_COLORS['土'];
                return TYPE_COLORS['魔法'];
            }
            if (/战技/.test(t)) return TYPE_COLORS['战技'];
            if (/武技|剑|斩|劈|锤|弓|枪|拳/.test(t)) return TYPE_COLORS['武技'];
            // 生产体系：锻造 / 炼金 / 工艺（附魔、制作）
            if (/锻造|打造|铁匠|熔炼|淬火|铸/.test(t)) return TYPE_COLORS['锻造'];
            if (/炼金|药剂|蒸馏|调配|魔药|药水|毒剂/.test(t)) return TYPE_COLORS['炼金'];
            if (/工艺|制作|制造|附魔|工坊|木工|缝纫/.test(t)) return TYPE_COLORS['工艺'];
            return null;
        }
        // 流派识别：从区块名/文本推断七大魔法流派（元素/符文/塑能/死灵/召唤/圣光/暗能）+ 元素子类，
        // 用于施法结算按流派差异化染色与专属特效
        function detectElement(text) {
            var t = text || '';
            if (/符文/.test(t)) return 'rune';
            if (/塑能/.test(t)) return 'kinesis';
            if (/死灵|尸术|灵术|亡灵/.test(t)) return 'necro';
            if (/召唤/.test(t)) return 'summon';
            if (/暗能|暗影|虚空/.test(t)) return 'void';
            if (/神术|圣光|信仰|光系/.test(t)) return 'holy';
            if (/火/.test(t)) return 'fire';
            if (/冰/.test(t)) return 'ice';
            if (/水/.test(t)) return 'water';
            if (/风/.test(t)) return 'wind';
            if (/雷/.test(t)) return 'thunder';
            if (/土|岩/.test(t)) return 'earth';
            if (/魔法|术/.test(t)) return 'arcane';
            return null;
        }
        function getPhaseMeta(name) {
            if (isApocalypse) {
                if (/符文/.test(name)) return { c: '#3a7a5a', i: '✳️' };
                if (/塑能/.test(name)) return { c: '#6a5aa8', i: '✹' };
                if (/死灵|尸术|灵术/.test(name)) return { c: '#6a4a6a', i: '💀' };
                if (/召唤/.test(name)) return { c: '#5a6aa8', i: '✶' };
                if (/暗能|暗影|虚空/.test(name)) return { c: '#4a3a4a', i: '🌑' };
                if (/神术|圣光|信仰/.test(name)) return { c: '#9a8a2a', i: '☀' };
                if (/魔法|术/.test(name)) return { c: '#7a5ad0', i: '✧' };
                if (/战技/.test(name)) return { c: '#b0602a', i: '⚒' };
                if (/攻击|武技/.test(name)) return { c: '#a02030', i: '⚔' };
                if (/升级/.test(name)) return { c: '#4ae07a', i: '⬆' };
                // 生产体系（锻造/炼金/工艺）
                if (/锻造|打造|熔炼|铁匠|淬火|铸/.test(name)) return { c: '#b0602a', i: '🔨' };
                if (/炼金|药剂|蒸馏|调配/.test(name)) return { c: '#4a8a5a', i: '⚗️' };
                if (/生产|制作|工艺|附魔|工坊/.test(name)) return { c: '#8a6a3a', i: '🛠' };
                return { c: '#7a4a6a', i: '⚄' };
            }
            if (/符文/.test(name)) return { c: '#3a5a4a', i: '✳️' };
            if (/塑能/.test(name)) return { c: '#4a3a6a', i: '✹' };
            if (/死灵|尸术|灵术/.test(name)) return { c: '#5a3a4a', i: '💀' };
            if (/召唤/.test(name)) return { c: '#4a3a6a', i: '✶' };
            if (/暗能|暗影|虚空/.test(name)) return { c: '#3a2a3a', i: '🌑' };
            if (/神术|圣光|信仰/.test(name)) return { c: '#b8892a', i: '☀' };
            if (/魔法|术/.test(name)) return { c: '#2a4a8a', i: '✧' };
            if (/战技/.test(name)) return { c: '#a06020', i: '⚒' };
            if (/攻击|武技/.test(name)) return { c: '#9a3b2a', i: '⚔' };
            if (/升级/.test(name)) return { c: '#d4af37', i: '⬆' };
            // 生产体系（锻造/炼金/工艺）
            if (/锻造|打造|熔炼|铁匠|淬火|铸/.test(name)) return { c: '#8a4a1a', i: '🔨' };
            if (/炼金|药剂|蒸馏|调配/.test(name)) return { c: '#2f6a4a', i: '⚗️' };
            if (/生产|制作|工艺|附魔|工坊/.test(name)) return { c: '#7a5a2a', i: '🛠' };
            return { c: '#a07828', i: '⚄' };
        }
        // 位阶徽章：从 MVU 变量读角色等阶（主角经 persona 名匹配 / 同伴直接查表）
        function getActorRank(name) {
            try {
                if (!name) return null;
                var stat = null;
                if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
                    stat = (Mvu.getMvuData({ type: 'message', message_id: 'latest' }) || {}).stat_data;
                }
                if (!stat) return null;
                var n = String(name).trim();
                // 主角：经当前 persona 名匹配
                var heroName = null;
                try { if (typeof getCurrentPersonaName === 'function') heroName = getCurrentPersonaName(); } catch (e) {}
                if (heroName && n === String(heroName).trim()) {
                    var hr = stat.主角 && stat.主角.等阶;
                    return hr ? String(hr) : null;
                }
                // 同伴：直接查表
                if (stat.同伴 && stat.同伴[n]) {
                    var cr = stat.同伴[n].等阶;
                    return cr ? String(cr) : null;
                }
                return null;
            } catch (e) { return null; }
        }
        function rankBadgeHtml(rank) {
            var r = String(rank || '').trim();
            if (!r) return '';
            return '<span class="rank-badge rank-' + r + '">◈ ' + r + '</span> ';
        }
        // 卷首题记：从酒馆变量读 世界.日期 / 世界.时间 / 世界.当前地点（回退当前位置）
        function buildHeadSub() {
            try {
                var stat = null;
                if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
                    stat = (Mvu.getMvuData({ type: 'message', message_id: 'latest' }) || {}).stat_data;
                }
                var w = (stat && stat.世界) || {};
                var parts = [];
                if (w.日期) parts.push(String(w.日期));
                if (w.时间) parts.push(String(w.时间));
                var loc = w.当前地点 || w.当前位置;
                if (loc) parts.push(String(loc));
                return parts.join(' · ') || (isApocalypse ? '终焉纪元 · 莫尔加纳 · 深渊之忆' : '圣光历 · 阿尔比恩王国 · 冒险者公会笔录');
            } catch (e) {
                return isApocalypse ? '终焉纪元 · 莫尔加纳 · 深渊之忆' : '圣光历 · 阿尔比恩王国 · 冒险者公会笔录';
            }
        }
        // 卷首副标题：按「卷首题头」开关决定是否渲染
        function headSubHtml() {
            return SETTINGS.headSub ? '<div class="head-sub">' + buildHeadSub() + '</div>' : '';
        }
        function getTagClass(key, value) {
            var k = (key || '').toLowerCase();
            var v = (value || '').toLowerCase();
            if (/^hp/i.test(k) || /^hp\b/i.test(v)) return 'tag tag-hp';
            if (/^mp/i.test(k) || /^mp\b/i.test(v)) return 'tag tag-mp';
            if (/^sp/i.test(k) || /^sp\b/i.test(v)) return 'tag tag-sp';
            if (/^角色$|^行动者$|^濒死者$|^目标$|^攻方$|^守方$|^施法者$/.test(k)) return 'tag tag-char';
            if (/^掷骰$|^死亡豁免$/.test(k)) return 'tag tag-dice';
            // 经验值相关
            if (/exp|经验值|经验/.test(k) || /^最终获得/.test(k)) return 'tag tag-exp';
            // 升级相关
            if (/^总等级$|^未分配属性点$|^待分配职业等级$|^等级提升$/.test(k)) return 'tag tag-levelup';
            if (/伤害/.test(k)) return 'tag tag-dmg';
            if (/^防御值$|^防御$|^难度dc$/.test(k)) return 'tag tag-def';
            if (/^动作$|^技能$|^检定项目$|^招式$|^附赠动作$/.test(k)) return 'tag tag-skill';
            if (/^资源消耗$|^资源剩余$/.test(k)) return 'tag tag-resource';
            if (/^先攻序列$|^序列$|^回合/.test(k)) return 'tag tag-round';
            if (/^环境$/.test(k)) return 'tag tag-env';
            if (/^状态$|^状态施加$|^状态变更$|^附加状态$|^累计状态$|^状态保留$/.test(k)) return 'tag tag-status';
            if (/^类型$/.test(k)) return 'tag tag-type';
            if (/^\s*\d+\s*(?:->|→)\s*\d+\s*$/.test(v)) {
                var nums = v.match(/(\d+)[\s]*(?:→|->)[\s]*(\d+)/);
                if (nums && nums.length >= 3) {
                    return parseInt(nums[2]) < parseInt(nums[1]) ? 'tag tag-change-down' : 'tag tag-change-up';
                }
            }
            if (/^判定结果$|^结果$|^最终结果$/.test(k)) {
                if (/大成功|暴击|自然20|胜利/.test(v)) return 'tag tag-crit';
                if (/大失败|自然1|失败|死亡|全灭/.test(v)) return 'tag tag-fail';
                if (/未命中|未中|失手|落空/.test(v)) return 'tag tag-general';
                if (/成功|命中|稳定|苏醒/.test(v)) return 'tag tag-hit';
            }
            // 生产相关（锻造/防具/炼金/工艺）
            if (/^制作者$|^工匠$|^铁匠$|^炼金师$/.test(k)) return 'tag tag-char';
            if (/^材料$|^材料消耗$|^配方$|^原料$|^素材$|^图纸$/.test(k)) return 'tag tag-craft-mat';
            if (/^成品$|^产出$|^产量$/.test(k)) return 'tag tag-craft-out';
            if (/^品质$/.test(k)) {
                if (/史诗|传说|神话|唯一/.test(v)) return 'tag tag-crit';
                if (/精良|稀有/.test(v)) return 'tag tag-craft-out';
                return 'tag tag-craft-mat';
            }
            if (/^工序$|^步骤$|^耗时$|^工时$|^工坊$|^工具$|^火候$|^锻打$|^淬火$|^熔炼$/.test(k)) return 'tag tag-craft-step';
            return 'tag tag-general';
        }
        function detectRowType(text) {
            if (!SETTINGS.critHighlight) return ''; // 关闭开关时不做暴击/大失败/升级高亮
            if (/资源剩余/.test(text)) return 'resource-row';
            if (/大成功|暴击|自然20|胜利/.test(text)) return 'crit-row';
            if (/大失败|自然1/.test(text)) return 'fail-row';
            if (/等级提升|未分配属性点|待分配职业等级/.test(text)) return 'upgrade-row';
            return '';
        }
        // 行图标：只按「键名」与「判定结果值」判断，避免效果/备注文案里的"动作/技能"字样误触发 ⚔
        function rowIconFromPairs(pairs) {
            var keys = [], jud = null, typeVal = null;
            pairs.forEach(function(p) {
                var i = p.indexOf(':');
                if (i === -1) return;
                var k = p.substring(0, i).trim();
                keys.push(k);
                if (/^判定结果$|^结果$|^最终结果$/.test(k)) jud = p.substring(i + 1).trim();
                if (/^类型$/.test(k)) typeVal = p.substring(i + 1).trim();
            });
            function has(pat) { for (var x = 0; x < keys.length; x++) { if (pat.test(keys[x])) return true; } return false; }
            if (has(/^(总等级|未分配属性点|待分配职业等级|等级提升)$/)) return '⬆';
            if (jud && /大成功|暴击|自然20|胜利/.test(jud)) return '✦';
            if (jud && /大失败|自然1/.test(jud)) return '☠';
            // 按「类型」字段着色图标（武技⚔ / 战技⚒ / 魔法✧ / 神术☀ / 元素）
            var tm = (SETTINGS.flowStyle && typeVal) ? getTypeMeta(typeVal) : null;
            if (tm) return tm.i;
            if (has(/^(攻方|守方|动作|技能|招式|附赠动作)$/)) return '⚔';
            if (has(/^(施法者|法术|魔法)$/)) return '✧';
            if (has(/^(检定项目|掷骰|死亡豁免)$/)) return '⚄';
            return '';
        }
        // 资源条：把 "45/45" 渲染成按比例填充的色条
        function resBar(key, value, cls) {
            var m = value.match(/^(\d+)\s*\/\s*(\d+)$/);
            if (!m) return null;
            var cur = parseInt(m[1], 10), max = parseInt(m[2], 10);
            var pct = max > 0 ? Math.min(100, Math.round(cur / max * 100)) : 0;
            return '<span class="kv"><span class="key">' + key + '</span><span class="tag ' + cls + ' res-tag"><i class="res-fill" style="width:' + pct + '%"></i><span class="res-text">' + value + '</span></span></span> ';
        }
        // 角色状态解析：把「名字 HP x/y MP x/y SP x/y ...」渲染为一个灰色小框（名字 + 各资源数值）
        // 例：行人 HP 23/23 MP 12/23 / 巨型穴居鼠A/B/C HP 8/8
        // 兼容紧凑格式（名字与资源、资源与资源之间可有/无空格，尾部可带 (xN) 备注）：
        //   行人HP 23/23MP 6/23SP 0/0 / 穴居鼠AHP 15/15 / 后方鼠群 HP 15/15 (x4)
        function charStatusHtml(text) {
            if (!SETTINGS.charBox) return null; // 关闭开关时回退普通文本/标签渲染
            var s = String(text || '').trim();
            if (!s) return null;
            // 提取全部资源块
            var res = s.match(/(?:HP|MP|SP)\s*\d+\s*\/\s*\d+/ig);
            if (!res || res.length === 0) return null;
            // 名字 = 去掉资源块后的剩余文本；尾部 (xN) 备注单独保留
            var name = s.replace(/(?:HP|MP|SP)\s*\d+\s*\/\s*\d+/ig, '').trim();
            var note = '';
            var nm = name.match(/^(.*?)\s*(\([^)]*\))\s*$/);
            if (nm) { name = nm[1]; note = nm[2]; }
            if (!name) return null;
            var html = '<span class="char-box"><span class="char-name">' + name + '</span>';
            res.forEach(function(seg) {
                var rm = seg.match(/^(HP|MP|SP)\s*(\d+)\s*\/\s*(\d+)$/i);
                if (!rm) return;
                var cls = rm[1].toLowerCase() === 'hp' ? 'hp' : rm[1].toLowerCase() === 'mp' ? 'mp' : 'sp';
                html += '<span class="res-mini ' + cls + '">' + rm[1].toUpperCase() + ' ' + rm[2] + '/' + rm[3] + '</span>';
            });
            if (note) html += '<span class="char-note">' + note + '</span>';
            html += '</span>';
            return html;
        }
        // 角色群状态解析：「队伍状态/敌人状态/资源剩余: 名字 HP x/y | MP x/y | SP x/y | 名字2 ...」
        // 把每个角色的 HP/MP/SP 归入同一个灰框（兼容协议一行全员格式）
        function groupStatusHtml(text) {
            if (!SETTINGS.groupStatus || !SETTINGS.charBox) return null;
            var m = String(text || '').match(/^(队伍状态|敌人状态|队伍|敌人|资源剩余)\s*[:：]\s*([\s\S]+)$/);
            if (!m) return null;
            var body = m[2];
            var tokens = body.split(/\s*\|\s*/).map(function(t) { return t.trim(); }).filter(Boolean);
            var groups = [];
            tokens.forEach(function(tok) {
                if (/^(HP|MP|SP)\s*\d+\s*\/\s*\d+$/i.test(tok)) {
                    if (!groups.length) groups.push({ name: '', res: [] });
                    groups[groups.length - 1].res.push(tok);
                } else {
                    groups.push({ name: tok, res: [] });
                }
            });
            var html = '';
            groups.forEach(function(g) {
                if (!g.name) return;
                var seg = g.res.length ? (g.name + ' ' + g.res.join(' ')).trim() : g.name;
                var c = charStatusHtml(seg);
                if (c) html += c + ' ';
            });
            return html || null;
        }
        function parseAndRender(rawText) {
            var contentDiv = document.getElementById('battleContent');
            if (!rawText || rawText.trim() === '') {
                contentDiv.innerHTML = '<div style="text-align:center;color:' + (isApocalypse ? '#8a5a6a' : '#a0522d') + ';font-weight:600;letter-spacing:2px;">' + (isApocalypse ? '※ 深渊之中空无一物 ※' : '※ 羊皮卷上未记载任何信息 ※') + '</div>';
                return;
            }
            rawText = rawText.replace(/<\/?(战斗结算|检定结算|升级结算|生产结算)>/g, '');
              // ☆ 咏唱特效：咏唱中/咏唱完成待释放/前摇 相关值渲染为金色脉动光晕
              rawText = rawText.replace(/咏唱(?:中|完成待释放|前摇|状态)[：:]\s*[^|\n]{0,40}/g, function(seg){ return '<span class="cast-glow">' + seg + '</span>'; });
            var lines = rawText.split(/\n/);
            // 预扫描：为每个区块确定流派（取区块内首个「类型」字段，整块按该流派染色，替代行级染色）
            var blockElems = [];
            var blockTypeSet = [];
            var scanIdx = -1;
            lines.forEach(function(line, li) {
                if (!SETTINGS.flowStyle) return; // 关闭七大流派染色时跳过预扫描
                var st = line.trim();
                if (SETTINGS.fullWidth) st = st.replace(/：/g, ':');
                if (/^\{.+\}$/.test(st)) {
                    // 仅第一行的根级卷首标记（渲染走标题分支、不计数）跳过；其余 {} 均计数（与渲染保持一致）
                    if (li === 0 && /^[【\{](战斗结算|检定结算|升级结算|生产结算)[】\}]$/.test(st)) return;
                    scanIdx++;
                    blockElems[scanIdx] = detectElement(st);
                    return;
                }
                if (scanIdx >= 0 && /(?:^|\|)\s*类型\s*:/.test(st)) {
                    var stm = st.match(/类型\s*:\s*([^\|]+)/);
                    if (stm) {
                        var ste = detectElement(stm[1]);
                        // 只取区块内首个类型行（避免后续类型行覆盖）
                        if (ste && !blockTypeSet[scanIdx]) { blockElems[scanIdx] = ste; blockTypeSet[scanIdx] = true; }
                    }
                }
            });
            var html = '';
            var inBlock = false;
            var hasTitle = false;
            var firstLine = true;
            var blockIdx = -1;
            lines.forEach(function(line) {
                var t = line.trim();
                if (SETTINGS.fullWidth) t = t.replace(/｜/g, '|').replace(/：/g, ':');
                if (t === '') return;
                // 卷首题头：仅第一行若为「战斗结算/检定结算/升级结算」（{} 或 【】 形式）才作为整卷标题
                if (firstLine && !hasTitle) {
                    firstLine = false;
                    var m1 = t.match(/^[【\{](战斗结算|检定结算|升级结算|生产结算)[】\}]$/);
                    if (m1) {
                        hasTitle = true;
                        html += '<div class="scroll-header"><div class="head-orn">' + (isApocalypse ? '⚸ ─── ✦ ─── ⚸' : '❦ ─── ✦ ─── ❦') + '</div><div class="head-title">' + m1[1] + '</div>' + headSubHtml() + '<div class="head-rule"></div></div>';
                        return;
                    }
                    // 首行非根级标记（如 {战况总览 - 第X轮}）：显示通用卷首题头
                    hasTitle = true;
                    html += '<div class="scroll-header"><div class="head-orn">' + (isApocalypse ? '⚸ ─── ✦ ─── ⚸' : '❦ ─── ✦ ─── ❦') + '</div><div class="head-title">' + (isApocalypse ? '终焉纪事' : '战斗记录') + '</div>' + headSubHtml() + '<div class="head-rule"></div></div>';
                }
                if (/^\{.+\}$/.test(t)) {
                    var name = t.replace(/[{}]/g, '');
                    // 判定区块
                    if (inBlock) html += '</div>';
                    blockIdx++;
                    var pm = getPhaseMeta(name);
                    var elem = SETTINGS.flowStyle ? (blockElems[blockIdx] || detectElement(name)) : null;
                    var pcls = /神术|圣光|信仰/.test(name) ? 'ph-holy' : (/魔法|术/.test(name) ? 'ph-magic' : (/战技/.test(name) ? 'ph-arts' : (/攻击|武技/.test(name) ? 'ph-weapon' : (/锻造|打造|熔炼|铁匠|炼金|药剂|生产|制作|工艺|附魔|工坊/.test(name) ? 'ph-craft' : 'ph-generic'))));
                    html += '<div class="phase-block ' + pcls + (elem ? ' elem-' + elem : '') + '">';
                    inBlock = true;
                    html += '<div class="phase-marker"><span class="phase-title"><span class="phase-icon">' + pm.i + '</span>' + name + '<span class="phase-icon">' + pm.i + '</span></span></div>';
                    return;
                }
                if (t.indexOf('|') !== -1) {
                    t = t.replace(/：/g, ':').replace(/｜/g, '|');
                    var clean = t.replace(/^\|\s*/, '').replace(/\s*\|?\s*$/, '');
                    // 独立成行的「vs 防御/DC 数值」（AI 拆行多段掷骰的尾巴）→ 渲染为目标标签
                    var vsM = clean.match(/^vs\s*(防御|DC|难度)\s*:?\s*(\d+)/i);
                    if (vsM) {
                        html += '<div class="data-row"><span class="row-icon">🎯</span><span class="tag tag-def">vs ' + vsM[1] + ' ' + vsM[2] + '</span></div>';
                        return;
                    }
                    // 无冒号的经验值更新行：| - 名字 经验值 旧 -> 新/所需 |
                    var expM = clean.match(/^-\s*(.+?)\s+经验值\s+(\d+)\s*(?:->|→)\s*(\d+)\s*\/\s*(\d+)\s*$/);
                    if (expM) {
                        var expDelta = parseInt(expM[3], 10) - parseInt(expM[2], 10);
                        html += '<div class="data-row exp-update-row"><span class="row-icon">⬆</span><span class="tag tag-char">' + expM[1] + '</span> <span class="tag tag-exp">经验值 ' + expM[2] + ' → ' + expM[3] + '/' + expM[4] + (expDelta > 0 ? '（+' + expDelta + '）' : '') + '</span></div>';
                        return;
                    }
                    if (!/\|[^|]+:/.test(t)) {
                        html += '<div class="narrative">' + clean + '</div>';
