                    }
                    var pairs = clean.split(/\s*\|\s*/);
                    var extra = detectRowType(clean);
                    var icon = rowIconFromPairs(pairs);
                    var rowHtml = '<div class="data-row' + (extra ? ' ' + extra : '') + '">';
                    if (icon) rowHtml += '<span class="row-icon">' + icon + '</span>';
                    // 行内是否属于 EXP 结算（EXP计算/经验值更新/最终获得EXP）→ 后续无 key 片段统一染绿 tag-exp
                    var rowExp = /(?:EXP计算|基础EXP总计|最终获得EXP|经验值更新|经验值|EXP)/i.test(clean);
                    // 位阶徽章：识别行内角色名（角色/行动者/攻方/守方/施法者），从 MVU 变量读等阶
                    var actorName = null, actorRank = null, rankIn = false;
                    var hasRankField = false; // 行内是否已有「位阶:」文本字段（有则不再插徽章，避免重复）
                    if (SETTINGS.rankBadge) {
                        // 先独立扫描所有 pair，确认是否已有「位阶:」字段（不能在找到角色名后 break，否则漏检位阶）
                        for (var hf = 0; hf < pairs.length; hf++) {
                            var hfi = pairs[hf].indexOf(':');
