                            var rci = pairs[ri].indexOf(':');
                            if (rci === -1) continue;
                            var rkey = pairs[ri].substring(0, rci).trim();
                            if (/^(角色|行动者|攻方|守方|施法者)$/.test(rkey)) {
                                actorName = pairs[ri].substring(rci + 1).trim().replace(/(?:HP|MP|SP)\s*\d+\s*\/\s*\d+/ig, '').trim();
                                break;
                            }
                        }
                        if (actorName) actorRank = getActorRank(actorName);
                    }
                    var pushRank = function() { if (actorRank && !rankIn && !hasRankField) { rowHtml += rankBadgeHtml(actorRank); rankIn = true; } };
                    var rowDone = false;
                    pairs.forEach(function(pair) {
