                            // 角色状态行：value 形如「名字 HP x/y MP x/y ...」→ 名字标签 + 资源条
                            if (SETTINGS.groupStatus && SETTINGS.charBox && /^(队伍状态|敌人状态|队伍|敌人|资源剩余)$/.test(key)) {
                                // 群状态（协议一行全员格式）：整行按角色分组，HP/MP/SP 归入同一灰框
