                            var resOnly = value.match(/^(HP|MP|SP)\s+(\d+)\s*\/\s*(\d+)$/i);
                            if (resOnly && key !== '类型' && SETTINGS.charBox) {
                                pushRank();
                                var rcls = resOnly[1].toLowerCase() === 'hp' ? 'hp' : resOnly[1].toLowerCase() === 'mp' ? 'mp' : 'sp';
                                rowHtml += '<span class="char-box"><span class="char-name">' + key + '</span><span class="res-mini ' + rcls + '">' + resOnly[1].toUpperCase() + ' ' + resOnly[2] + '/' + resOnly[3] + '</span></span> ';
                                return;
                            }
                            // HP/MP/SP 资源条
                            var bar = (/^(hp|mp|sp)$/i.test(key) && SETTINGS.resourceBar) ? resBar(key, value, cls) : null;
                            if (bar) { pushRank(); rowHtml += bar; return; }
                            // 类型标签：按体系/元素动态着色
                            var tmeta = (key === '类型' && SETTINGS.flowStyle) ? getTypeMeta(value) : null;
                            if (tmeta) {
                                rowHtml += '<span class="kv"><span class="key">' + key + '</span><span class="tag type-tag" style="border-color:' + tmeta.c + ';color:' + tmeta.c + ';background:linear-gradient(180deg,' + hexA(tmeta.c, .14) + ',' + hexA(tmeta.c, .03) + ');">' + tmeta.i + ' ' + value + '</span></span> ';
                            } else {
                                rowHtml += '<span class="kv"><span class="key">' + key + '</span><span class="' + cls + '">' + value + '</span></span> ';
                            }
                        } else {
