                            // 掷骰片段（第X次 d20(...) = ...）→ 骰子标签
                            var rollF = fragment.match(/^(?:第?\s*\d+\s*次\s*[:：]?\s*)?d\d+\s*[（(]/i);
                            if (rollF) { rowHtml += '<span class="tag tag-dice">' + fragment + '</span> '; return; }
                            // vs 目标片段（vs 防御/DC 数值）→ 目标标签
                            var vsF = fragment.match(/^vs\s*(防御|DC|难度)\s*:?\s*\d+/i);
                            if (vsF) { rowHtml += '<span class="tag tag-def">🎯 ' + fragment + '</span> '; return; }
                            // 紧凑角色状态片段：如「千早 HP 33/33 SP 21/21」
                            var cstFrag = charStatusHtml(fragment);
                            if (cstFrag) { rowHtml += cstFrag + ' '; return; }
                            if (/^HP\s+\d+\/\d+$/i.test(fragment)) rowHtml += resBar('HP', fragment.replace(/^HP\s+/i, ''), 'tag tag-hp');
                            else if (/^MP\s+\d+\/\d+$/i.test(fragment)) rowHtml += resBar('MP', fragment.replace(/^MP\s+/i, ''), 'tag tag-mp');
                            else if (/^SP\s+\d+\/\d+$/i.test(fragment)) rowHtml += resBar('SP', fragment.replace(/^SP\s+/i, ''), 'tag tag-sp');
                            else if (/^HP\b/i.test(fragment)) rowHtml += '<span class="tag tag-hp">' + fragment + '</span> ';
                            else if (/^MP\b/i.test(fragment)) rowHtml += '<span class="tag tag-mp">' + fragment + '</span> ';
                            else if (/^SP\b/i.test(fragment)) rowHtml += '<span class="tag tag-sp">' + fragment + '</span> ';
                            else if (/^\s*\d+\s*(?:->|→)\s*\d+\s*$/.test(fragment)) {
                                var fn = fragment.match(/(\d+)[\s]*(?:->|→)[\s]*(\d+)/);
                                var fcls = parseInt(fn[2]) < parseInt(fn[1]) ? 'tag tag-change-down' : 'tag tag-change-up';
                                rowHtml += '<span class="' + fcls + '">' + fragment + '</span> ';
                            }
                            else if (/→|->/.test(fragment)) rowHtml += '<span class="' + (rowExp ? 'tag tag-exp' : 'tag tag-general') + '">' + fragment + '</span> ';
                            else if (fragment) rowHtml += '<span class="kv"><span class="' + (rowExp ? 'tag tag-exp' : 'val-text') + '">' + fragment + '</span></span> ';
                        }
                    });
                    rowHtml += '</div>';
                    html += rowHtml;
                } else if (/^-{2,}$/.test(t)) {
                    html += '<div class="divider"></div>';
                } else if (/^\[.+\]$/.test(t)) {
                    html += '<div class="sub-head">' + t.replace(/[\[\]]/g, '') + '</div>';
                } else if (/^(EXP计算|基础EXP总计|最终获得EXP|经验值更新|备注|资源剩余|战果简述|队伍状态|敌人状态)$/.test(t)) {
                    html += '<div class="label-row">' + t + '</div>';
                } else {
                    // 角色状态行（紧凑格式：行人HP 23/23MP 6/23SP 0/0 等）→ 灰框，与队伍/敌人状态保持一致的视觉
                    var cstLine = charStatusHtml(t);
                    if (cstLine) {
                        html += '<div class="data-row resource-row"><span class="row-icon">✦</span>' + cstLine + '</div>';
                        return;
                    }
                    // 无包裹的经验值更新行：| 名字 经验值 旧 -> 新/所需 |（AI 可能不带 | 前缀，逐人一行）
                    var expLine = t.trim().match(/^(.+?)\s+经验值\s+(\d+)\s*(?:->|→)\s*(\d+)\s*\/\s*(\d+)\s*$/);
                    if (expLine) {
                        var expDelta2 = parseInt(expLine[3], 10) - parseInt(expLine[2], 10);
                        html += '<div class="data-row exp-update-row"><span class="row-icon">⬆</span><span class="tag tag-char">' + expLine[1] + '</span> <span class="tag tag-exp">经验值 ' + expLine[2] + ' → ' + expLine[3] + '/' + expLine[4] + (expDelta2 > 0 ? '（+' + expDelta2 + '）' : '') + '</span></div>';
                        return;
                    }
                    // 裸掷骰行（AI 多段掷骰常把「第X次/连击」拆成独立行）：渲染为骰子标签，避免变正文
                    var diceLine = t.match(/^\s*(?:第?\s*\d+\s*次\s*[:：]?\s*)?d\d+\s*[（(]/i);
                    if (diceLine) {
                        html += '<div class="data-row"><span class="row-icon">⚄</span><span class="tag tag-dice">' + t + '</span></div>';
                        return;
                    }
                    // 回合交替标记（→ 下一回合：…）单独成行时渲染为回合标签
                    var roundM = t.match(/^(?:→\s*)?(下一回合|回合结束)\s*[:：]?\s*(.+)$/);
                    if (roundM) {
                        html += '<div class="data-row"><span class="row-icon">⏭</span><span class="tag tag-round">' + roundM[1] + ' → ' + roundM[2] + '</span></div>';
                        return;
                    }
                    html += '<div class="narrative">' + t + '</div>';
                }
            });
            if (inBlock) html += '</div>';
            html += '<div class="scroll-footer"><span class="foot-orn">─ ✦ ─</span><span>' + (isApocalypse ? '魔潮吞没至此' : '记录至此 · 冒险者公会') + '</span><span class="foot-orn">─ ✦ ─</span><span class="foot-seal">' + (isApocalypse ? '魔' : '印') + '</span></div>';
            contentDiv.innerHTML = html;
        }
        function init() {
            try {
                var raw = document.getElementById('rawData').innerText || '';
                parseAndRender(raw);
            } catch (e) {
                document.getElementById('battleContent').innerHTML = '<div style="color:#8b2222; text-align:center;font-weight:600;">※ 卷轴破损，无法解读 ※</div>';
            }
        }
        // ===== 渲染设置系统：勾选选项即开关对应正则/功能 =====
        // 持久化：localStorage（本机记忆）+ 酒馆聊天变量「战斗轮渲染设置」（跨设备），读取优先级 localStorage > 聊天变量 > 默认
        var DEFAULT_SETTINGS = {
            flowStyle: true,       // 七大流派整块染色（流派底色/边框/标题/角标/纹理）
            flowFx: true,          // 流派角标与背景纹理特效
            critHighlight: true,   // 暴击/大失败/升级高亮行
            fullWidth: true,       // 全角符号兼容（：→:、｜→|、→）
            charBox: true,         // 角色状态紧凑灰框（行人 HP 23/23 之类）
            groupStatus: true,     // 群状态一行格式（队伍状态/敌人状态 一行全员）
            resourceBar: true,     // 资源条彩色填充（HP/MP/SP 按比例色条）
            apocalypseForce: false, // 强制暗黑风
            apocalypseBlock: false, // 禁用暗黑风（两者都关时跟随聊天变量「终焉纪元IF线」）
            headSub: true,          // 卷首题头（日期/地点副标题）
            rankBadge: true         // 位阶徽章（从变量读角色等阶，显示在资源条旁）
        };
        var SETTINGS = {};
        var isApocalypse = false;
        var DEFAULT_TYPE_COLORS = {};
        (function() { for (var k in TYPE_COLORS) DEFAULT_TYPE_COLORS[k] = { c: TYPE_COLORS[k].c, i: TYPE_COLORS[k].i }; })();
        function loadSettings() {
            var s = {};
            try {
                var raw = null;
                try { if (window.localStorage) raw = localStorage.getItem('battle_scroll_settings_v1'); } catch (e) {}
                if (!raw && typeof getVariables === 'function') {
                    try { raw = getVariables({ type: 'chat' })['战斗轮渲染设置'] || null; } catch (e) {}
                }
                if (raw) s = JSON.parse(raw) || {};
            } catch (e) { s = {}; }
            SETTINGS = {};
            for (var k in DEFAULT_SETTINGS) SETTINGS[k] = (typeof s[k] === 'boolean') ? s[k] : DEFAULT_SETTINGS[k];
        }
        function saveSettings() {
            try {
                var j = JSON.stringify(SETTINGS);
                try { if (window.localStorage) localStorage.setItem('battle_scroll_settings_v1', j); } catch (e) {}
                try {
                    if (typeof insertOrAssignVariables === 'function') {
                        insertOrAssignVariables({ name: '战斗轮渲染设置', value: j, type: 'chat' });
                    }
                } catch (e) {}
            } catch (e) {}
        }
        // 应用开关到全局：暗黑风三态（强制开/强制关/跟随聊天变量）+ 流派特效类
        function applySettings() {
            document.body.classList.toggle('flowfx-off', !SETTINGS.flowFx);
            var varDark = false;
            try { if (typeof getVariables === 'function') varDark = !!getVariables({ type: 'chat' })['终焉纪元IF线']; } catch (e) {}
            // 优先级：禁用暗黑风（硬性关）> 强制暗黑风（硬性开）> 跟随聊天变量「终焉纪元IF线」
            isApocalypse = SETTINGS.apocalypseBlock ? false : (SETTINGS.apocalypseForce ? true : varDark);
            document.body.classList.toggle('apocalypse', isApocalypse);
            // 先恢复默认类型配色，再按需覆盖为暗黑系（保证开关来回切换不残留）
            for (var k in DEFAULT_TYPE_COLORS) TYPE_COLORS[k] = { c: DEFAULT_TYPE_COLORS[k].c, i: DEFAULT_TYPE_COLORS[k].i };
            if (isApocalypse) {
                TYPE_COLORS['武技'] = { c: '#a02030', i: '⚔' };
                TYPE_COLORS['战技'] = { c: '#b0602a', i: '⚒' };
                TYPE_COLORS['魔法'] = { c: '#7a5ad0', i: '✧' };
                TYPE_COLORS['神术'] = { c: '#9a8a2a', i: '☀' };
                TYPE_COLORS['火'] = { c: '#c03040', i: '🔥' };
                TYPE_COLORS['水'] = { c: '#4a6ae0', i: '💧' };
                TYPE_COLORS['风'] = { c: '#2e8b74', i: '🌪️' };
                TYPE_COLORS['雷'] = { c: '#8a8a20', i: '⚡' };
                TYPE_COLORS['冰'] = { c: '#6a9ac0', i: '❄️' };
                TYPE_COLORS['土'] = { c: '#8a6a4a', i: '⛰️' };
                TYPE_COLORS['符文'] = { c: '#3a7a5a', i: '✳️' };
                TYPE_COLORS['塑能'] = { c: '#6a5aa8', i: '✹' };
                TYPE_COLORS['死灵'] = { c: '#6a4a6a', i: '💀' };
                TYPE_COLORS['召唤'] = { c: '#5a6aa8', i: '✶' };
                TYPE_COLORS['暗能'] = { c: '#4a3a4a', i: '🌑' };
            }
        }
        function bindSettings() {
            var fab = document.getElementById('settingsFab');
            var panel = document.getElementById('settingsPanel');
            if (!fab || !panel) return;
            function closePanel() { panel.classList.remove('open'); fab.classList.remove('active'); }
            fab.addEventListener('click', function() {
                panel.classList.toggle('open');
                fab.classList.toggle('active', panel.classList.contains('open'));
            });
            var closeBtn = document.getElementById('settingsClose');
            if (closeBtn) closeBtn.addEventListener('click', closePanel);
            var saved = document.getElementById('settingsSaved');
            function flashSaved() {
                if (!saved) return;
                saved.classList.add('show');
                clearTimeout(saved._t);
                saved._t = setTimeout(function() { saved.classList.remove('show'); }, 1200);
            }
            panel.querySelectorAll('input[data-key]').forEach(function(inp) {
                var key = inp.getAttribute('data-key');
                inp.checked = !!SETTINGS[key];
                inp.addEventListener('change', function() {
                    SETTINGS[key] = inp.checked;
                    saveSettings();
                    applySettings();
                    init(); // 立即按新开关重新渲染
                    flashSaved();
                });
            });
            var resetBtn = document.getElementById('settingsReset');
            if (resetBtn) resetBtn.addEventListener('click', function() {
                for (var k in DEFAULT_SETTINGS) SETTINGS[k] = DEFAULT_SETTINGS[k];
                panel.querySelectorAll('input[data-key]').forEach(function(inp) { inp.checked = !!SETTINGS[inp.getAttribute('data-key')]; });
                saveSettings();
                applySettings();
                init();
                flashSaved();
            });
        }
        $(function() {
            loadSettings();
            applySettings();
            bindSettings();
            init();
        });
    </script>
</body>
</html>
